package storage

// Byte-level backward-reading controls for the V2 reserved timestamp bits.
//
// The oracle for every legacy vector below is the on-disk layout of
// 69115e8a2 pkg/storage/edge_compact.go before the reserved-bit change, spelled
// out here as pinned literals:
//
//	[0]      format byte (0x02 V1, 0x03 V2)
//	[1]      flags (bit 0 AutoGenerated, bit 1 VisibilitySuppressed; 69115e8a2
//	         defined no other bit and ignored the rest on decode)
//	[2..9]   StartNode numID, big-endian uint64
//	[10..17] EndNode numID
//	[18..25] CreatedAt, UTC UnixNano as int64, big-endian
//	[26..33] UpdatedAt, same encoding
//	[34..41] Confidence, IEEE-754 float64 bits
//	[42..]   uvarint(typeLen) + type bytes
//	[...]    msgpack properties (V1 map[string]any, V2 tokenized map[uint64]any)
//
// The vectors are literals, never the encoder's own output, so an encoder and
// decoder that agree with each other but disagree with 69115e8a2 fail here.
// 69115e8a2 encoded time.Time{} through t.UTC().UnixNano(), whose int64
// overflow is -6795364578871345152 ns, i.e. the 1754-08-30T22:43:41.128654848Z
// instant. The new reserved bits are additive: they change no field offset,
// length, or raw timestamp byte, and no existing body's old meaning changes.
// This is backward-reading proof for pre-existing payloads, not a migration and
// not a claim to recover timestamps that the old format already lost. An old
// binary reading a new image ignores the reserved bits and still returns the
// 1754 instant for an unset relationship time.

import (
	"encoding/binary"
	"encoding/hex"
	"math"
	"path/filepath"
	"testing"
	"time"

	"github.com/dgraph-io/badger/v4"
	fixtureowner "github.com/orneryd/nornicdb/internal/testfixture"
	"github.com/stretchr/testify/require"
)

const (
	// legacyEdgeFixedHeaderBytes is the fixed-width prefix of both versions.
	legacyEdgeFixedHeaderBytes = 1 + 1 + 8 + 8 + 8 + 8 + 8
	// legacyWrappedZeroNanos is 69115e8a2's stored form of time.Time{}:
	// time.Time{}.UTC().UnixNano() overflows int64 and wraps to 1754-08-30.
	legacyWrappedZeroNanos int64 = -6795364578871345152
)

// legacyWrappedZeroNanosBits is the uint64 big-endian form the old encoder wrote.
const legacyWrappedZeroNanosBits uint64 = 0xa1b203eb3d1a0000

// legacyEdgeImage is one pinned pre-change body plus the field values that the
// pre-change layout gives it. Every field is asserted at its documented offset.
type legacyEdgeImage struct {
	name          string
	format        byte
	image         string // hex literal of the whole body
	flags         byte
	start, end    uint64
	createdNanos  int64
	updatedNanos  int64
	confidence    float64
	edgeType      string
	propertiesHex string // hex literal of the trailing properties payload
}

// newEdgeImage is one body the current encoder must produce for the same input,
// pinned as a literal so the encoder cannot be its own oracle.
type newEdgeImage struct {
	name          string
	edge          *Edge
	start, end    uint64
	image         string // hex literal of the whole body
	flags         byte
	createdNanos  int64
	updatedNanos  int64
	created       time.Time
	updated       time.Time
	edgeType      string
	confidence    float64
	autoGenerated bool
	suppressed    bool
}

// TestLegacyEdgeWrappedZeroNanosIsThe1754Instant pins the overflow that gives
// zero-timestamp bodies written by 69115e8a2 their historical meaning.
func TestLegacyEdgeWrappedZeroNanosIsThe1754Instant(t *testing.T) {
	require.Equal(t, legacyWrappedZeroNanos, time.Time{}.UTC().UnixNano(),
		"69115e8a2 stored time.Time{} as t.UTC().UnixNano()")
	wrapped := legacyWrappedZeroNanos
	require.Equal(t, legacyWrappedZeroNanosBits, uint64(wrapped),
		"the pinned on-disk uint64 is the two's complement of the wrapped int64 nanos")
	require.Equal(t,
		time.Date(1754, time.August, 30, 22, 43, 41, 128654848, time.UTC),
		time.Unix(0, legacyWrappedZeroNanos).UTC(),
		"the wrapped year-1 zero time is the 1754 instant")
}

