func decodeLegacyEdgeImageHex(t *testing.T, image string) []byte {
	t.Helper()
	body, err := hex.DecodeString(image)
	require.NoError(t, err, "pinned legacy vector must be valid hex")
	return body
}

// assertPinnedLegacyEdgeLayout proves the pinned body still occupies the
// 69115e8a2 offsets and lengths, so no field moved or changed width.
func assertPinnedLegacyEdgeLayout(t *testing.T, vector legacyEdgeImage) []byte {
	t.Helper()
	body := decodeLegacyEdgeImageHex(t, vector.image)
	require.Equal(t, vector.format, body[0], "%s: format byte at [0]", vector.name)
	require.Equal(t, vector.flags, body[1], "%s: flags byte at [1]", vector.name)
	require.Equal(t, vector.start, binary.BigEndian.Uint64(body[2:10]), "%s: start numID at [2..9]", vector.name)
	require.Equal(t, vector.end, binary.BigEndian.Uint64(body[10:18]), "%s: end numID at [10..17]", vector.name)
	require.Equal(t, uint64(vector.createdNanos), binary.BigEndian.Uint64(body[18:26]), "%s: CreatedAt at [18..25]", vector.name)
	require.Equal(t, uint64(vector.updatedNanos), binary.BigEndian.Uint64(body[26:34]), "%s: UpdatedAt at [26..33]", vector.name)
	require.Equal(t, math.Float64bits(vector.confidence), binary.BigEndian.Uint64(body[34:42]), "%s: Confidence at [34..41]", vector.name)

	typeLen := int(body[legacyEdgeFixedHeaderBytes])
	require.Equal(t, len(vector.edgeType), typeLen, "%s: uvarint type length at [42]", vector.name)
	require.Equal(t, vector.edgeType, string(body[legacyEdgeFixedHeaderBytes+1:legacyEdgeFixedHeaderBytes+1+typeLen]),
		"%s: type bytes follow the fixed header", vector.name)
	properties := decodeLegacyEdgeImageHex(t, vector.propertiesHex)
	require.Equal(t, properties, body[legacyEdgeFixedHeaderBytes+1+typeLen:], "%s: properties payload follows the type", vector.name)
	require.Equal(t, legacyEdgeFixedHeaderBytes+1+typeLen+len(properties), len(body),
		"%s: body length is header + type length byte + type + properties", vector.name)

	// The shared production parse must locate the properties payload at the
	// same offset the pinned body places it.
	parsed := new(Edge)
	start, end, offset, err := decodeEdgeCompactHeaderInto(body, vector.format, parsed)
	require.NoError(t, err, "%s: pinned body must parse", vector.name)
	require.Equal(t, vector.start, start)
	require.Equal(t, vector.end, end)
	require.Equal(t, legacyEdgeFixedHeaderBytes+1+typeLen, offset, "%s: properties offset", vector.name)
	return body
}

// TestEdgeCompactV1PinnedLegacyVectorsKeepOldDecode pins the V1 reader against
// pinned 69115e8a2 bodies: epoch stays epoch, the wrapped zero keeps its 1754
// meaning, ordinary instants stay exact, and upper flag bits stay ignored.
func TestEdgeCompactV1PinnedLegacyVectorsKeepOldDecode(t *testing.T) {
	for _, vector := range legacyEdgeImages() {
		if vector.format != edgeFormatCompactV1 {
			continue
		}
		t.Run(vector.name, func(t *testing.T) {
			body := assertPinnedLegacyEdgeLayout(t, vector)

			edge, start, end, err := decodeEdgeCompactV1(body)
			require.NoError(t, err)
			require.Equal(t, vector.start, start)
			require.Equal(t, vector.end, end)
			require.Equal(t, vector.edgeType, edge.Type)
			require.Equal(t, time.Unix(0, vector.createdNanos).UTC(), edge.CreatedAt,
				"V1 CreatedAt keeps the exact pre-change nanos meaning")
			require.Equal(t, time.Unix(0, vector.updatedNanos).UTC(), edge.UpdatedAt,
				"V1 UpdatedAt keeps the exact pre-change nanos meaning")
			require.Equal(t, vector.createdNanos, edge.CreatedAt.UnixNano(),
				"V1 CreatedAt is not normalized or reinterpreted")
			require.Equal(t, vector.updatedNanos, edge.UpdatedAt.UnixNano(),
				"V1 UpdatedAt is not normalized or reinterpreted")
			require.Equal(t, math.Float64bits(vector.confidence), math.Float64bits(edge.Confidence))
			require.Equal(t, vector.flags&edgeFlagAutoGen != 0, edge.AutoGenerated)
			require.Equal(t, vector.flags&edgeFlagSuppressed != 0, edge.VisibilitySuppressed)

			if vector.propertiesHex == "81a16ba176" {
				require.Equal(t, "v", edge.Properties["k"], "V1 string-keyed properties still decode")
			} else {
				require.Empty(t, edge.Properties)
			}

			if vector.createdNanos == legacyWrappedZeroNanos && vector.updatedNanos == legacyWrappedZeroNanos {
				require.False(t, edge.CreatedAt.IsZero(),
					"an old V1 body storing the wrapped zero time stays the 1754 instant, never time.Time{}")
				require.Equal(t,
					time.Date(1754, time.August, 30, 22, 43, 41, 128654848, time.UTC),
					edge.CreatedAt,
					"historical V1 zero-time overflow meaning is preserved verbatim")
			}
			if vector.createdNanos == 0 && vector.updatedNanos == 0 {
				require.False(t, edge.CreatedAt.IsZero(), "epoch 0 must not be reclassified as unset")
				require.Equal(t, time.Unix(0, 0).UTC(), edge.CreatedAt)
			}
			if vector.flags&0x0c != 0 {
				require.False(t, edge.CreatedAt.IsZero(), "upper V1 flag bits must not erase the timestamp")
				require.False(t, edge.UpdatedAt.IsZero())
			}
		})
	}
}

// TestEdgeCompactV2PinnedLegacyVectorsKeepOldDecode pins the V2 reader against
// pinned 69115e8a2 bodies: flag bytes 0x00..0x03, epoch 0, +/-1 ns and the
// wrapped year-1 zero all keep the exact pre-change decode.
func TestEdgeCompactV2PinnedLegacyVectorsKeepOldDecode(t *testing.T) {
	engine := newTestEngine(t)
	for _, vector := range legacyEdgeImages() {
		if vector.format != edgeFormatCompactV2 {
			continue
		}
		t.Run(vector.name, func(t *testing.T) {
			body := assertPinnedLegacyEdgeLayout(t, vector)

			edge, start, end, err := engine.decodeEdgeCompactV2(nil, "ns", body)
			require.NoError(t, err)
			require.Equal(t, vector.start, start)
			require.Equal(t, vector.end, end)
			require.Equal(t, vector.edgeType, edge.Type)
			require.Equal(t, time.Unix(0, vector.createdNanos).UTC(), edge.CreatedAt,
				"an old V2 CreatedAt keeps the exact pre-change nanos meaning")
			require.Equal(t, time.Unix(0, vector.updatedNanos).UTC(), edge.UpdatedAt,
				"an old V2 UpdatedAt keeps the exact pre-change nanos meaning")
			require.Equal(t, vector.createdNanos, edge.CreatedAt.UnixNano(),
				"an old V2 CreatedAt is not normalized to zero or epoch")
			require.Equal(t, vector.updatedNanos, edge.UpdatedAt.UnixNano(),
				"an old V2 UpdatedAt is not normalized to zero or epoch")
			require.Equal(t, math.Float64bits(vector.confidence), math.Float64bits(edge.Confidence))
			require.Equal(t, vector.flags&edgeFlagAutoGen != 0, edge.AutoGenerated)
			require.Equal(t, vector.flags&edgeFlagSuppressed != 0, edge.VisibilitySuppressed)
			require.Empty(t, edge.Properties)

			if vector.createdNanos == 0 && vector.updatedNanos == 0 {
				require.Equal(t, time.Unix(0, 0).UTC(), edge.CreatedAt,
					"old epoch 0 stays the epoch instant")
				require.False(t, edge.CreatedAt.IsZero(), "old epoch 0 must not become unset")
			}
			if vector.createdNanos == legacyWrappedZeroNanos {
				require.Equal(t,
					time.Date(1754, time.August, 30, 22, 43, 41, 128654848, time.UTC),
					edge.CreatedAt,
					"old V2 wrapped zero keeps the historical 1754 meaning")
				require.False(t, edge.CreatedAt.IsZero())
			}
		})
	}
}

// TestEdgeCompactV1WriterKeepsLegacyZeroTimeImage proves the V1 writer is
// unchanged: an unset V1 time still produces the pinned 69115e8a2 image
// byte-for-byte, with no reserved bit set.
func TestEdgeCompactV1WriterKeepsLegacyZeroTimeImage(t *testing.T) {
	var pinned legacyEdgeImage
	for _, vector := range legacyEdgeImages() {
		if vector.name == "v1-wrapped-zero-legacy-image" {
			pinned = vector
		}
	}
	require.NotEmpty(t, pinned.image)

	body, err := encodeEdgeCompactV1(&Edge{
		Type:       "LINK",
		CreatedAt:  time.Time{},
		UpdatedAt:  time.Time{},
		Confidence: 1.0,
		Properties: map[string]any{"k": "v"},
	}, 1, 2)
	require.NoError(t, err)
	require.Equal(t, pinned.image, hex.EncodeToString(body),
		"the V1 writer must emit the pinned legacy image for unset times")
	require.Zero(t, body[1]&(1<<2), "the V1 writer must not set the CreatedAt-unset bit")
	require.Zero(t, body[1]&(1<<3), "the V1 writer must not set the UpdatedAt-unset bit")

	edge, _, _, err := decodeEdgeCompactV1(body)
	require.NoError(t, err)
	require.Equal(t, time.Unix(0, legacyWrappedZeroNanos).UTC(), edge.CreatedAt,
		"the V1 round trip keeps the legacy wrapped-zero meaning")
}

// TestEdgeCompactV2WriterKeepsLegacyHeaderBytesForNonzeroTimes pins that a
// normal nonzero V2 image is byte-identical to the pinned 69115e8a2 image.
func TestEdgeCompactV2WriterKeepsLegacyHeaderBytesForNonzeroTimes(t *testing.T) {
	var pinned legacyEdgeImage
	for _, vector := range legacyEdgeImages() {
		if vector.name == "v2-ordinary-nonzero" {
			pinned = vector
		}
	}
	require.NotEmpty(t, pinned.image)

	body := encodeEdgeCompactHeader(edgeFormatCompactV2, &Edge{
		Type:          "RELATED",
		CreatedAt:     time.Unix(0, pinned.createdNanos).UTC(),
		UpdatedAt:     time.Unix(0, pinned.updatedNanos).UTC(),
		Confidence:    0.25,
		AutoGenerated: true,
	}, pinned.start, pinned.end, 0)
	body = append(body, 0x00) // empty tokenized properties payload

	require.Equal(t, pinned.image, hex.EncodeToString(body),
		"a nonzero V2 image must stay byte-identical to the pinned legacy image")
	require.Zero(t, body[1]&(1<<2))
	require.Zero(t, body[1]&(1<<3))

	engine := newTestEngine(t)
	edge, start, end, err := engine.decodeEdgeCompactV2(nil, "ns", body)
	require.NoError(t, err)
	require.Equal(t, pinned.start, start)
	require.Equal(t, pinned.end, end)
	require.Equal(t, pinned.edgeType, edge.Type)
	require.Equal(t, time.Unix(0, pinned.createdNanos).UTC(), edge.CreatedAt)
	require.Equal(t, time.Unix(0, pinned.updatedNanos).UTC(), edge.UpdatedAt)
	require.True(t, edge.AutoGenerated)
	require.False(t, edge.VisibilitySuppressed)
}

// TestEdgeCompactV2UnsetBitsAreAdditive pins the new reserved-bit images: exact
// bit masks 1<<2 and 1<<3, unchanged field offsets, unchanged raw timestamp
// bytes, no conflation of epoch, and no erasure of the other field or of the
// other edge metadata.
func TestEdgeCompactV2UnsetBitsAreAdditive(t *testing.T) {
	const (
		createdUnsetMask = byte(1 << 2)
		updatedUnsetMask = byte(1 << 3)
	)
	// The masks are the parent's declared bit assignments (1<<2, 1<<3); the
	// assertions below require the encoder and decoder to honour exactly them.
	require.Zero(t, createdUnsetMask&(edgeFlagAutoGen|edgeFlagSuppressed),
		"the new mask must not reuse the two pre-existing flag bits")
	require.Zero(t, updatedUnsetMask&(edgeFlagAutoGen|edgeFlagSuppressed))
	require.Zero(t, createdUnsetMask&updatedUnsetMask, "the two unset bits are distinct")

	images := []newEdgeImage{
		{
			name:          "both-unset",
			edge:          &Edge{Type: "L", CreatedAt: time.Time{}, UpdatedAt: time.Time{}, Confidence: 1.0, AutoGenerated: true, VisibilitySuppressed: true},
			start:         7,
			end:           8,
			image:         "030f00000000000000070000000000000008a1b203eb3d1a0000a1b203eb3d1a00003ff0000000000000014c00",
			flags:         0x0f,
			createdNanos:  legacyWrappedZeroNanos,
			updatedNanos:  legacyWrappedZeroNanos,
			created:       time.Time{},
			updated:       time.Time{},
			edgeType:      "L",
			confidence:    1.0,
			autoGenerated: true,
			suppressed:    true,
		},
		{
			name:         "created-unset-only",
			edge:         &Edge{Type: "LINK", CreatedAt: time.Time{}, UpdatedAt: time.Unix(0, 1).UTC(), Confidence: 0.5},
			start:        7,
			end:          8,
			image:        "030400000000000000070000000000000008a1b203eb3d1a000000000000000000013fe0000000000000044c494e4b00",
			flags:        0x04,
			createdNanos: legacyWrappedZeroNanos,
			updatedNanos: 1,
			created:      time.Time{},
			updated:      time.Unix(0, 1).UTC(),
			edgeType:     "LINK",
			confidence:   0.5,
		},
		{
			name:         "updated-unset-only",
			edge:         &Edge{Type: "REL", CreatedAt: time.Unix(0, -1).UTC(), UpdatedAt: time.Time{}, Confidence: 0.5},
			start:        7,
			end:          8,
			image:        "030800000000000000070000000000000008ffffffffffffffffa1b203eb3d1a00003fe00000000000000352454c00",
			flags:        0x08,
			createdNanos: -1,
			updatedNanos: legacyWrappedZeroNanos,
			created:      time.Unix(0, -1).UTC(),
			updated:      time.Time{},
			edgeType:     "REL",
			confidence:   0.5,
		},
		{
			name:         "epoch-not-unset",
			edge:         &Edge{Type: "LINK", CreatedAt: time.Unix(0, 0).UTC(), UpdatedAt: time.Unix(0, 0).UTC(), Confidence: 1.0},
			start:        9,
			end:          10,
			image:        "03000000000000000009000000000000000a000000000000000000000000000000003ff0000000000000044c494e4b00",
			flags:        0x00,
			createdNanos: 0,
			updatedNanos: 0,
			created:      time.Unix(0, 0).UTC(),
			updated:      time.Unix(0, 0).UTC(),
			edgeType:     "LINK",
			confidence:   1.0,
		},
	}
	engine := newTestEngine(t)

	for _, image := range images {
		t.Run(image.name, func(t *testing.T) {
			body := encodeEdgeCompactHeader(edgeFormatCompactV2, image.edge, image.start, image.end, 0)
			body = append(body, 0x00) // empty tokenized properties payload

			require.Equal(t, image.image, hex.EncodeToString(body),
				"the encoder image must match the pinned literal")
			require.Equal(t, image.flags, body[1])
			require.Equal(t, image.start, binary.BigEndian.Uint64(body[2:10]))
			require.Equal(t, image.end, binary.BigEndian.Uint64(body[10:18]))
			require.Equal(t, uint64(image.createdNanos), binary.BigEndian.Uint64(body[18:26]),
				"the raw CreatedAt bytes keep the pre-change encoding")
			require.Equal(t, uint64(image.updatedNanos), binary.BigEndian.Uint64(body[26:34]),
				"the raw UpdatedAt bytes keep the pre-change encoding")
			require.Equal(t, math.Float64bits(image.confidence), binary.BigEndian.Uint64(body[34:42]))
			require.Equal(t, image.edge.CreatedAt.IsZero(), body[1]&createdUnsetMask != 0,
				"bit 2 means exactly CreatedAt.IsZero()")
			require.Equal(t, image.edge.UpdatedAt.IsZero(), body[1]&updatedUnsetMask != 0,
				"bit 3 means exactly UpdatedAt.IsZero()")

			edge, start, end, err := engine.decodeEdgeCompactV2(nil, "ns", body)
			require.NoError(t, err)
			require.Equal(t, image.start, start)
			require.Equal(t, image.end, end)
			require.Equal(t, image.created, edge.CreatedAt, "decoded CreatedAt must be the encoded field, unnormalized")
			require.Equal(t, image.updated, edge.UpdatedAt, "decoded UpdatedAt must be the encoded field, unnormalized")
			require.Equal(t, image.created.IsZero(), edge.CreatedAt.IsZero())
			require.Equal(t, image.updated.IsZero(), edge.UpdatedAt.IsZero())
			if image.created.IsZero() {
				require.False(t, edge.CreatedAt.Equal(time.Unix(0, 0).UTC()),
					"an unset CreatedAt must not decode as epoch")
				require.False(t, edge.CreatedAt.Equal(time.Unix(0, legacyWrappedZeroNanos).UTC()),
					"an unset CreatedAt must not decode as the legacy 1754 instant")
			}
			if image.updated.IsZero() {
				require.False(t, edge.UpdatedAt.Equal(time.Unix(0, 0).UTC()),
					"an unset UpdatedAt must not decode as epoch")
			}
			require.Equal(t, image.edgeType, edge.Type)
			require.Equal(t, math.Float64bits(image.confidence), math.Float64bits(edge.Confidence),
				"Confidence must not be disturbed by the unset bits")
			require.Equal(t, image.autoGenerated, edge.AutoGenerated,
				"AutoGenerated must not be disturbed by the unset bits")
			require.Equal(t, image.suppressed, edge.VisibilitySuppressed,
				"VisibilitySuppressed must not be disturbed by the unset bits")
		})
	}
}

// openStorageFixtureEngine constructs and owns one engine at its test boundary.
func openStorageFixtureEngine(t *testing.T, dir string) *BadgerEngine {
	t.Helper()
	engine, err := fixtureowner.TrackResult[*BadgerEngine](t, ErrStorageClosed)(NewBadgerEngine(dir))
	require.NoError(t, err)
	require.NotNil(t, engine)
	return engine
}

// readStoredEdgeBody returns the persisted compact body for id.
func readStoredEdgeBody(t *testing.T, engine *BadgerEngine, id EdgeID) []byte {
	t.Helper()
	var body []byte
	require.NoError(t, engine.DB().View(func(txn *badger.Txn) error {
		item, err := txn.Get(edgeKey(id))
		if err != nil {
			return err
		}
		body, err = item.ValueCopy(nil)
		return err
	}))
	return body
}

// TestAcceptedRelationshipUnsetTimestampsSurviveNativeStorage drives the
// public decoded accepted-command entry on unset relationship timestamps and
// requires the stored images, close/reopen and native backup/restore to return
// exact zero -- not epoch, not the legacy 1754 instant -- with unchanged
// counts and unchanged other fields. The neighboring epoch edge proves the new
// unset bits do not swallow a real epoch instant.
func TestAcceptedRelationshipUnsetTimestampsSurviveNativeStorage(t *testing.T) {
	dir := t.TempDir()
	base := openStorageFixtureEngine(t, dir)

	seed := time.Unix(1, 0).UTC()
	unset := &Edge{
		ID:         "test:unset-created-updated",
		StartNode:  "test:a",
		EndNode:    "test:b",
		Type:       "UNSET",
		Properties: map[string]any{"w": "x"},
		Confidence: 0.25,
		CreatedAt:  time.Time{},
		UpdatedAt:  time.Time{},
	}
	epochNeighbor := &Edge{
		ID:         "test:epoch-neighbor",
		StartNode:  "test:a",
		EndNode:    "test:b",
		Type:       "EPOCH",
		Properties: map[string]any{"e": "1"},
		Confidence: 1.0,
		CreatedAt:  time.Unix(0, 0).UTC(),
		UpdatedAt:  time.Unix(0, 1).UTC(),
	}
	ops := []Operation{
		{Type: OpCreateNode, Node: &Node{ID: "test:a", Labels: []string{"Compact"}, CreatedAt: seed, UpdatedAt: seed}},
		{Type: OpCreateNode, Node: &Node{ID: "test:b", Labels: []string{"Compact"}, CreatedAt: seed, UpdatedAt: seed}},
		{Type: OpCreateEdge, Edge: unset},
		{Type: OpCreateEdge, Edge: epochNeighbor},
	}
	receipt, err := SubmitAcceptedEntityTransaction(t.Context(), base,
		EntityTransactionEnvelope{Version: EntityTransactionVersion, Namespace: "test", LogicalTxID: "edge-compact-unset-time", Mode: CommitModeExplicit},
		ops, nil)
	require.NoError(t, err)
	require.NoError(t, receipt.Wait(t.Context()))

	assertImages := func(t *testing.T, engine *BadgerEngine) {
		t.Helper()
		stored, err := engine.GetStoredEdge(t.Context(), unset.ID)
		require.NoError(t, err)
		require.True(t, stored.CreatedAt.IsZero(),
			"accepted unset relationship CreatedAt must stay exactly zero, got %s", stored.CreatedAt.UTC().Format(time.RFC3339Nano))
		require.True(t, stored.UpdatedAt.IsZero(),
			"accepted unset relationship UpdatedAt must stay exactly zero, got %s", stored.UpdatedAt.UTC().Format(time.RFC3339Nano))
		require.False(t, stored.CreatedAt.Equal(time.Unix(0, 0).UTC()), "unset must not read as epoch")
		require.False(t, stored.CreatedAt.Equal(time.Unix(0, legacyWrappedZeroNanos).UTC()), "unset must not read as the legacy 1754 instant")
		require.Equal(t, unset.StartNode, stored.StartNode)
		require.Equal(t, unset.EndNode, stored.EndNode)
		require.Equal(t, unset.Type, stored.Type)
		require.Equal(t, "x", stored.Properties["w"], "relationship properties must be unchanged")
		require.Equal(t, math.Float64bits(unset.Confidence), math.Float64bits(stored.Confidence),
			"relationship confidence must be unchanged")

		neighbor, err := engine.GetStoredEdge(t.Context(), epochNeighbor.ID)
		require.NoError(t, err)
		require.False(t, neighbor.CreatedAt.IsZero(), "an epoch relationship must not become unset")
		require.Equal(t, epochNeighbor.CreatedAt, neighbor.CreatedAt,
			"the real epoch instant must be retained exactly")
		require.Equal(t, epochNeighbor.UpdatedAt, neighbor.UpdatedAt,
			"the +1ns instant must be retained exactly")
		require.Equal(t, "1", neighbor.Properties["e"], "the neighboring relationship keeps its properties")

		nodes, err := engine.NodeCount(t.Context())
		require.NoError(t, err)
		require.EqualValues(t, 2, nodes)
		edges, err := engine.EdgeCount(t.Context())
		require.NoError(t, err)
		require.EqualValues(t, 2, edges)

		unsetBody := readStoredEdgeBody(t, engine, unset.ID)
		require.Equal(t, edgeFormatCompactV2, unsetBody[0])
		require.NotZero(t, unsetBody[1]&(1<<2), "an unset CreatedAt must persist the reserved bit")
		require.NotZero(t, unsetBody[1]&(1<<3), "an unset UpdatedAt must persist the reserved bit")
		require.Equal(t, legacyWrappedZeroNanosBits, binary.BigEndian.Uint64(unsetBody[18:26]),
			"the persisted CreatedAt bytes keep the pre-change encoding")
		require.Equal(t, legacyWrappedZeroNanosBits, binary.BigEndian.Uint64(unsetBody[26:34]),
			"the persisted UpdatedAt bytes keep the pre-change encoding")

		neighborBody := readStoredEdgeBody(t, engine, epochNeighbor.ID)
		require.Zero(t, neighborBody[1]&(1<<2), "an epoch CreatedAt must not persist the unset bit")
		require.Zero(t, neighborBody[1]&(1<<3), "a +1ns UpdatedAt must not persist the unset bit")
		require.Equal(t, uint64(0), binary.BigEndian.Uint64(neighborBody[18:26]))
		require.Equal(t, uint64(1), binary.BigEndian.Uint64(neighborBody[26:34]))
	}

	assertImages(t, base)
	require.NoError(t, base.Close())

	reopened := openStorageFixtureEngine(t, dir)
	assertImages(t, reopened)

	backup := filepath.Join(t.TempDir(), "edge-unset.backup")
	require.NoError(t, reopened.Backup(backup))
	restored := openStorageFixtureEngine(t, t.TempDir())
	require.NoError(t, restored.Restore(backup))
	assertImages(t, restored)
	require.NoError(t, restored.Close())
	require.NoError(t, reopened.Close())
}
